      ),

      hr(),

      h4("Current status"),
      uiOutput("status_box"),

      hr(),

      h4("Event log"),
      div(class = "event-log", tableOutput("event_log")),

      hr(),

      div(
        class = "cleanup-note",
        strong("When you're done"),
        p(
