# Required packages:
# install.packages(c("shiny", "shinyjs"))
#
# Run:
# shiny::runApp("C:/Users/cawys/OneDrive - University of Edinburgh/08. SWITCH/Outdoor Classification/autographer_annotator_persistent_labels/autographer_annotator/app.R")

library(shiny)
library(shinyjs)

options(shiny.maxRequestSize = 1024^3)

`%||%` <- function(x, y) {
  if (is.null(x) || length(x) == 0L || is.na(x[1])) y else x
}

parse_autographer_time <- function(path) {
  nm <- basename(path)

  hit <- regmatches(
    nm,
    regexpr("[0-9]{8}_[0-9]{6}", nm, perl = TRUE)
  )

  if (length(hit) == 1L && nzchar(hit)) {
    parsed <- as.POSIXct(
      hit,
      format = "%Y%m%d_%H%M%S",
      tz = "UTC"
    )
    if (!is.na(parsed)) return(parsed)
  }

  file.info(path)$mtime
}

safe_minutes <- function(start_time, end_time) {
  if (is.na(start_time) || is.na(end_time)) return(NA_real_)
  max(0, as.numeric(difftime(end_time, start_time, units = "mins")))
}

build_intervals <- function(events, session_start, session_end, initial_state) {
  if (is.na(session_start) || is.na(session_end) || session_end < session_start) {
    return(data.frame())
  }

  state <- initial_state
  current_start <- session_start
  rows <- list()
  row_id <- 1L

  if (nrow(events) > 0L) {
    events <- events[order(events$time, events$event_id), , drop = FALSE]

    for (i in seq_len(nrow(events))) {
      event_time <- events$time[i]
      new_state <- events$new_state[i]

      if (is.na(event_time)) next
      event_time <- min(max(event_time, session_start), session_end)
      if (identical(new_state, state)) next

      rows[[row_id]] <- data.frame(
        interval_id = row_id,
        state = state,
        start_time = current_start,
        end_time = event_time,
        minutes = safe_minutes(current_start, event_time),
        stringsAsFactors = FALSE
      )

      row_id <- row_id + 1L
      state <- new_state
      current_start <- event_time
    }
  }

  rows[[row_id]] <- data.frame(
    interval_id = row_id,
    state = state,
    start_time = current_start,
    end_time = session_end,
    minutes = safe_minutes(current_start, session_end),
    stringsAsFactors = FALSE
  )

  do.call(rbind, rows)
}

